package br.com.marquesautodetail.api.favorito; import br.com.marquesautodetail.api.empresa.*;import br.com.marquesautodetail.api.empresa.dto.EmpresaResponse;import br.com.marquesautodetail.api.usuario.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class FavoritoService{ private final FavoritoRepository repo; private final UsuarioRepository usuarios; private final EmpresaRepository empresas; private final EmpresaService empresaService; public FavoritoService(FavoritoRepository repo,UsuarioRepository usuarios,EmpresaRepository empresas,EmpresaService empresaService){this.repo=repo;this.usuarios=usuarios;this.empresas=empresas;this.empresaService=empresaService;} private Usuario cliente(){String email=SecurityContextHolder.getContext().getAuthentication().getName(); Usuario u=usuarios.findByEmail(email).orElseThrow(); if(u.getRole()!=Role.CLIENTE) throw new IllegalArgumentException("Somente cliente usa favoritos"); return u;} @Transactional public void favoritar(Long empresaId){Usuario c=cliente(); Empresa e=empresas.findById(empresaId).orElseThrow(()->new IllegalArgumentException("Empresa não encontrada")); repo.findByClienteAndEmpresa(c,e).orElseGet(()->{Favorito f=new Favorito(); f.setCliente(c); f.setEmpresa(e); return repo.save(f);});} public List<EmpresaResponse> listar(){return repo.findByCliente(cliente()).stream().map(f->empresaService.toResponse(f.getEmpresa(),null,null)).toList();} @Transactional public void remover(Long empresaId){Usuario c=cliente(); Empresa e=empresas.findById(empresaId).orElseThrow(()->new IllegalArgumentException("Empresa não encontrada")); repo.deleteByClienteAndEmpresa(c,e);} }
